// The standard list, get, create, update and delete routes for a resource.
import type { Context, Hono } from "hono";
import { all, find, insert, remove, update } from "./store.js";
import { validate, type Issue, type Rule } from "./validate.js";

export type Op = "list" | "get" | "create" | "update" | "delete";

export type Resource = {
  path: string;
  table: string;
  ops: readonly Op[];
  rules: Record<string, Rule>;
  unique: readonly string[];
  slugs: Record<string, string>; // slug field -> the field it's made from
};

export function slugify(text: string): string {
  return text
    .toLowerCase()
    .normalize("NFKD")
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "");
}

const notFound = (c: Context) => c.json({ error: "not_found" }, 404);
const invalid = (c: Context, issues: Issue[]) => c.json({ error: "invalid_input", issues }, 400);

// Paths are built at runtime, so Hono can't type the :id param for us.
const idOf = (c: Context): string => c.req.param("id") ?? "";

async function body(c: Context): Promise<unknown> {
  return c.req.json().catch(() => undefined);
}

// prepare validates a body, derives slugs and checks unique fields.
function prepare(res: Resource, input: unknown, self?: string): { values: Record<string, unknown>; issues: Issue[] } {
  const { values, issues } = validate(res.rules, input, self !== undefined);
  for (const [slug, from] of Object.entries(res.slugs)) {
    if (typeof values[from] === "string") {
      values[slug] = slugify(values[from]);
    }
  }
  for (const field of res.unique) {
    if (values[field] !== undefined && all(res.table).some((row) => row.id !== self && row[field] === values[field])) {
      issues.push({ field, message: "already taken" });
    }
  }
  return { values, issues };
}

export function mount(app: Hono, res: Resource): void {
  const item = `${res.path}/:id`;
  if (res.ops.includes("list")) {
    app.get(res.path, (c) => c.json(all(res.table)));
  }
  if (res.ops.includes("get")) {
    app.get(item, (c) => {
      const row = find(res.table, idOf(c));
      return row ? c.json(row) : notFound(c);
    });
  }
  if (res.ops.includes("create")) {
    app.post(res.path, async (c) => {
      const { values, issues } = prepare(res, await body(c));
      return issues.length ? invalid(c, issues) : c.json(insert(res.table, values), 201);
    });
  }
  if (res.ops.includes("update")) {
    app.patch(item, async (c) => {
      const id = idOf(c);
      if (!find(res.table, id)) {
        return notFound(c);
      }
      const { values, issues } = prepare(res, await body(c), id);
      return issues.length ? invalid(c, issues) : c.json(update(res.table, id, values));
    });
  }
  if (res.ops.includes("delete")) {
    app.delete(item, (c) => (remove(res.table, idOf(c)) ? c.body(null, 204) : notFound(c)));
  }
}
